#!/usr/bin/env python3
# Session-260 (R-57) docs lockstep, part 3: the README program row's
# R-57 summary (prepended, the R-56 row demoted to "Previous:"), the
# worklog entry (prepended), and the session record
# (docs/session_103.md). Each edit asserts its OLD form.

def edit(path, old, new, count=1):
    src = open(path, encoding="utf-8").read()
    assert src.count(old) == count, f"{path}: anchor x{src.count(old)} (expected {count}): {old[:70]!r}"
    open(path, "w", encoding="utf-8").write(src.replace(old, new, count))
    print(f"  ok {path}: {old[:52]!r}")

